insert into public.menu_items values ('brasa-classic','burgers','{"id":"brasa-classic","name":"Brasa Classic","description":"O clássico que acende a vontade. Blend da casa na brasa, cheddar derretido e nosso molho secreto.","ingredients":"Pão brioche, blend bovino 180 g, cheddar, alface, tomate e maionese da casa.","categoryId":"burgers","price":3290,"image":"https://images.unsplash.com/photo-1568901346375-23c9450c58cd?auto=format&fit=crop&w=1000&q=85","available":true,"featured":true,"badge":"O favorito da casa","allergens":["Glúten","Leite","Ovos"],"prepMinutes":20,"groups":[{"id":"bread","name":"Seu pão","min":1,"max":1,"options":[{"id":"brioche","name":"Brioche artesanal","price":0},{"id":"australian","name":"Australiano","price":200}]},{"id":"point","name":"Ponto da carne","min":1,"max":1,"options":[{"id":"medium","name":"Ao ponto","price":0},{"id":"well","name":"Bem passado","price":0},{"id":"rare","name":"Malpassado","price":0}]},{"id":"extras","name":"Deixe do seu jeito","min":0,"max":4,"options":[{"id":"bacon","name":"Bacon crocante","price":600},{"id":"cheddar","name":"Cheddar extra","price":400},{"id":"patty","name":"Blend extra 180 g","price":1400},{"id":"onion","name":"Cebola caramelizada","price":300}]}],"modelUrl":"/models/brasa-classic.glb","modelCredit":"Modelo geométrico ilustrativo da demonstração. Não é uma digitalização do prato; adicionais não alteram o visual."}'::jsonb) on conflict(id) do nothing;
