insert into public.menu_items values ('double-fire','burgers','{"id":"double-fire","name":"Double Fire","description":"Duas carnes na brasa, queijo em dobro e o toque picante do nosso molho especial.","ingredients":"Pão australiano, dois blends de 120 g, cheddar, jalapeño e maionese picante.","categoryId":"burgers","price":4490,"image":"https://images.unsplash.com/photo-1571091718767-18b5b1457add?auto=format&fit=crop&w=1000&q=85","available":true,"featured":false,"badge":"Para quem tem fome","allergens":["Glúten","Leite","Ovos"],"prepMinutes":25,"groups":[{"id":"bread","name":"Seu pão","min":1,"max":1,"options":[{"id":"brioche","name":"Brioche artesanal","price":0},{"id":"australian","name":"Australiano","price":200}]},{"id":"point","name":"Ponto da carne","min":1,"max":1,"options":[{"id":"medium","name":"Ao ponto","price":0},{"id":"well","name":"Bem passado","price":0},{"id":"rare","name":"Malpassado","price":0}]},{"id":"extras","name":"Deixe do seu jeito","min":0,"max":4,"options":[{"id":"bacon","name":"Bacon crocante","price":600},{"id":"cheddar","name":"Cheddar extra","price":400},{"id":"patty","name":"Blend extra 180 g","price":1400},{"id":"onion","name":"Cebola caramelizada","price":300}]}],"modelUrl":"/models/double-fire.glb","modelCredit":"Modelo geométrico ilustrativo da demonstração. Não é uma digitalização do prato; adicionais não alteram o visual."}'::jsonb) on conflict(id) do nothing;
insert into public.menu_items values ('garden','burgers','{"id":"garden","name":"Garden Burger","description":"Cogumelos grelhados, burger de grão-de-bico e pesto fresco. Sabor que vem da terra.","ingredients":"Pão brioche, grão-de-bico, cogumelos, rúcula, queijo e pesto.","categoryId":"burgers","price":3490,"image":"https://images.unsplash.com/photo-1520072959219-c595dc870360?auto=format&fit=crop&w=1000&q=85","available":true,"featured":false,"badge":"Vegetariano","vegetarian":true,"allergens":["Glúten","Leite","Castanhas"],"prepMinutes":20,"groups":[{"id":"bread","name":"Seu pão","min":1,"max":1,"options":[{"id":"brioche","name":"Brioche artesanal","price":0},{"id":"australian","name":"Australiano","price":200}]}]}'::jsonb) on conflict(id) do nothing;
